1	//! The checker's answers kept for one snapshot, each asked once however many conversions want it, at once or later.
2	//!
3	//! The lanes of a run answer several components at a time over one converter ([`crate::convert::Converter`]), and
4	//! components of one library walk the same types in the same order: without this, two of them asked every question
5	//! twice, each missing a memo the other had not filled yet (Chakra: 520k of 732k `isReadonlySymbol` requests, 5,400 of
6	//! 8,900 `typeToString`). An answer is a function of the snapshot and the question alone, so which conversion asks it
7	//! first cannot show in the output.
8	
9	use std::future::Future;
10	use std::hash::Hash;
11	use std::sync::{Arc, Mutex, PoisonError};
12	
13	use rustc_hash::FxHashMap;
14	use tokio::sync::OnceCell;
15	
16	use crate::rpc::CallError;
17	
18	/// Answers by question. A question asked while another conversion waits for its answer waits for that answer instead
19	/// of asking again. An answer that failed is not kept: the next to ask asks again, as it would have without this.
20	pub(crate) struct Answers<K, V> {
21	    cells: Mutex<FxHashMap<K, Arc<OnceCell<V>>>>,
22	}
23	
24	impl<K, V> Default for Answers<K, V> {
25	    fn default() -> Self {
26	        Answers { cells: Mutex::default() }
27	    }
28	}
29	
30	impl<K: Eq + Hash, V: Clone> Answers<K, V> {
31	    /// The answer to `key`, from `ask` when it was not asked before.
32	    pub(crate) async fn get<F, Fut>(&self, key: K, ask: F) -> Result<V, CallError>
33	    where
34	        F: FnOnce() -> Fut,
35	        Fut: Future<Output = Result<V, CallError>>,
36	    {
37	        let cell = self.cells.lock().unwrap_or_else(PoisonError::into_inner).entry(key).or_default().clone();
38	        cell.get_or_try_init(ask).await.cloned()
39	    }
40	}
41	
42	#[cfg(test)]
43	mod tests {
44	    #![allow(clippy::unwrap_used)]
45	
46	    use std::sync::atomic::{AtomicU32, Ordering};
47	
48	    use super::*;
49	
50	    fn run<T>(work: impl Future<Output = T>) -> T {
51	        tokio::runtime::Builder::new_current_thread().build().unwrap().block_on(work)
52	    }
53	
54	    #[test]
55	    fn a_question_is_asked_once_and_a_failure_is_asked_again() {
56	        run(async {
57	            let answers: Answers<u64, u32> = Answers::default();
58	            let asked = AtomicU32::new(0);
59	            let ask = |value: u32| {
60	                let asked = &asked;
61	                move || async move {
62	                    asked.fetch_add(1, Ordering::Relaxed);
63	                    Ok(value)
64	                }
65	            };
66	            assert_eq!(answers.get(1, ask(10)).await.unwrap(), 10);
67	            assert_eq!(answers.get(1, ask(20)).await.unwrap(), 10);
68	            assert_eq!(answers.get(2, ask(30)).await.unwrap(), 30);
69	            assert_eq!(asked.load(Ordering::Relaxed), 2);
70	
71	            let failed = answers.get(3, || async { Err(CallError::Rejected("no".to_string())) }).await;
72	            assert!(matches!(failed, Err(CallError::Rejected(message)) if message == "no"));
73	            assert_eq!(answers.get(3, ask(40)).await.unwrap(), 40);
74	            assert_eq!(asked.load(Ordering::Relaxed), 3);
75	        });
76	    }
77	
78	    #[test]
79	    fn a_question_asked_while_it_is_being_answered_waits_for_that_answer() {
80	        run(async {
81	            let answers: Arc<Answers<u64, u32>> = Arc::default();
82	            let asked = Arc::new(AtomicU32::new(0));
83	            let (release, wait) = tokio::sync::oneshot::channel::<()>();
84	            let first = tokio::spawn({
85	                let (answers, asked) = (answers.clone(), asked.clone());
86	                async move {
87	                    answers
88	                        .get(1, || async move {
89	                            asked.fetch_add(1, Ordering::Relaxed);
90	                            wait.await.ok();
91	                            Ok(1)
92	                        })
93	                        .await
94	                }
95	            });
96	            // The first is now waiting on its answer.
97	            tokio::task::yield_now().await;
98	            let second = tokio::spawn({
99	                let (answers, asked) = (answers.clone(), asked.clone());
100	                async move {
101	                    answers
102	                        .get(1, || async move {
103	                            asked.fetch_add(1, Ordering::Relaxed);
104	                            Ok(2)
105	                        })
106	                        .await
107	                }
108	            });
109	            tokio::task::yield_now().await;
110	            release.send(()).unwrap();
111	            assert_eq!((first.await.unwrap().unwrap(), second.await.unwrap().unwrap()), (1, 1));
112	            assert_eq!(asked.load(Ordering::Relaxed), 1);
113	        });
114	    }
