1	//! Where each of a component's props is declared and what its JSDoc says, from the checker: the interface each of its
2	//! declarations sits in (`parent`, `declarations`), its description and its tags.
3	//!
4	//! A property symbol names the symbol it is a member of (`parent`); one a mapped type or an intersection made
5	//! (`Omit<Base, "x">`, `A & B`) names none, and its declarations are asked for the symbols they declare, whose parent
6	//! is the interface that wrote them. A declaration names its file the way the checker keys files, lower-cased where file
7	//! names are not case-sensitive; the file is reported as the program read it (`getSourceFileNames`), so
8	//! `parent.fileName` is the path on disk, as the structural pass reports it.
9	//!
10	//! Every answer is kept for the snapshot, keyed by what it depends on: a declaration's symbol by the declaration, a
11	//! parent's name by the parent, and a prop's JSDoc by its declarations, which is where the checker reads it, so the
12	//! props a library's components share (an instantiation or an `Omit` makes a new symbol for each) are asked about once.
13	
14	use std::collections::BTreeMap;
15	use std::sync::{Mutex, PoisonError};
16	
17	use caliper_docgen_core::types::PropParent;
18	use rustc_hash::FxHashMap;
19	use tokio::sync::OnceCell;
20	
21	use crate::convert::declared_in;
22	use crate::rpc::{Asking, CallError, CompactSymbol, JsDocTag, Rpc, SymbolInfo, SymbolRef, decode, flag};
23	
24	/// One prop to look up, and which of its JSDoc to ask for.
25	pub(crate) struct Asked<'a> {
26	    pub(crate) property: &'a SymbolInfo,
27	    /// Ask for its description: the structural pass has none for it.
28	    pub(crate) description: bool,
29	    /// Ask for its tags.
30	    pub(crate) tags: bool,
31	}
32	
33	/// What the checker says about where one prop is declared.
34	#[derive(Debug, Default)]
35	pub(crate) struct Declared {
36	    /// Empty when not asked for, or when it has none.
37	    pub(crate) description: String,
38	    /// Empty when not asked for, or when it has none.
39	    pub(crate) tags: BTreeMap<String, String>,
40	    pub(crate) parent: Option<PropParent>,
41	    pub(crate) declarations: Vec<PropParent>,
42	}
43	
44	/// The symbol a declaration declares, by the parent it names and the reference that asks about it.
45	type DeclaredSymbol = Option<(Option<CompactSymbol>, SymbolRef)>;
46	
47	/// What one snapshot's answers about declarations are kept as: they do not change inside it.
48	#[derive(Debug, Default)]
49	pub(crate) struct Memo {
50	    descriptions: Mutex<FxHashMap<String, String>>,
51	    tags: Mutex<FxHashMap<String, BTreeMap<String, String>>>,
52	    /// By the declaration handle.
53	    symbols: Mutex<FxHashMap<String, DeclaredSymbol>>,
54	    /// A parent symbol's name when it is an interface, else `None` (a type literal, a class, a module).
55	    parents: Mutex<FxHashMap<CompactSymbol, Option<String>>>,
56	    /// The program's files by the path a declaration names: the path itself, and lower-cased.
57	    files: OnceCell<FxHashMap<String, String>>,
58	}
59	
60	/// The request a batch holds for one answer, so the answer is read in the shape its method returns, and kept by key.
61	enum Pending {
62	    Description(String),
63	    Tags(String),
64	    Symbol(String),
65	}
66	
67	/// What a prop's JSDoc is kept by: its declarations, where the checker reads it, or the symbol when it has none.
68	fn jsdoc_key(property: &SymbolInfo) -> String {
69	    if property.declarations.is_empty() {
70	        property.reference.text().to_string()
71	    } else {
72	        property.declarations.join("\n")
73	    }
74	}
75	
76	/// The declarations, description and tags of every prop of `asked`, in its order: at most one round trip for what
77	/// this snapshot has not been asked yet, one for the parents it has not named yet, and one per snapshot for its files.
78	pub(crate) async fn declared(rpc: &Rpc, memo: &Memo, asked: &[Asked<'_>]) -> Result<Vec<Declared>, CallError> {
79	    let mut requests: Vec<(&'static str, Asking<'_>)> = Vec::new();
80	    let mut pending: Vec<Pending> = Vec::new();
81	    {
82	        let descriptions = memo.descriptions.lock().unwrap_or_else(PoisonError::into_inner);
83	        let tags = memo.tags.lock().unwrap_or_else(PoisonError::into_inner);
84	        let symbols = memo.symbols.lock().unwrap_or_else(PoisonError::into_inner);
85	        let mut queued = rustc_hash::FxHashSet::default();
86	        for prop in asked {
87	            let property = prop.property;
88	            let key = jsdoc_key(property);
89	            if prop.description && !descriptions.contains_key(&key) && queued.insert(("d", key.clone())) {
90	                requests.push(("getDocumentationComment", Asking::Symbol { symbol: &property.reference }));
91	                pending.push(Pending::Description(key.clone()));
92	            }
93	            if prop.tags && !tags.contains_key(&key) && queued.insert(("t", key.clone())) {
94	                requests.push(("getJsDocTags", Asking::Symbol { symbol: &property.reference }));
95	                pending.push(Pending::Tags(key));
96	            }
97	            if is_own_member(property) {
98	                continue;
99	            }
100	            for declaration in &property.declarations {
101	                if !symbols.contains_key(declaration) && queued.insert(("s", declaration.clone())) {
102	                    requests.push(("getSymbolOfDeclarationForChecker", Asking::Location { location: declaration }));
103	                    pending.push(Pending::Symbol(declaration.clone()));
104	                }
105	            }
106	        }
107	    }
108	    if !requests.is_empty() {
109	        let answers = rpc.batch(requests).await?;
110	        let mut descriptions = memo.descriptions.lock().unwrap_or_else(PoisonError::into_inner);
111	        let mut tags = memo.tags.lock().unwrap_or_else(PoisonError::into_inner);
112	        let mut symbols = memo.symbols.lock().unwrap_or_else(PoisonError::into_inner);
113	        for (request, answer) in pending.into_iter().zip(answers) {
114	            match request {
115	                Pending::Description(key) => {
116	                    descriptions.insert(key, decode(&answer)?);
117	                }
118	                Pending::Tags(key) => {
119	                    let answered: Option<Vec<JsDocTag>> = decode(&answer)?;
120	                    tags.insert(key, tags_of(answered.unwrap_or_default()));
121	                }
122	                Pending::Symbol(declaration) => {
123	                    let symbol: Option<SymbolInfo> = decode(&answer)?;
124	                    symbols.insert(declaration, symbol.map(|symbol| (symbol.parent, symbol.reference)));
125	                }
126	            }
127	        }
128	    }
129	
130	    // The symbol each declaration of each prop declares.
131	    let declares: Vec<Vec<DeclaredSymbol>> = {
132	        let symbols = memo.symbols.lock().unwrap_or_else(PoisonError::into_inner);
133	        asked
134	            .iter()
135	            .map(|prop| {
136	                let property = prop.property;
137	                if is_own_member(property) {
138	                    return vec![Some((property.parent.clone(), property.reference.clone()))];
139	                }
140	                property.declarations.iter().map(|declaration| symbols.get(declaration).cloned().flatten()).collect()
141	            })
142	            .collect()
143	    };
144	    let parents = parent_names(rpc, memo, &declares).await?;
145	    let files = if parents.values().any(Option::is_some) {
146	        Some(memo.files.get_or_try_init(|| program_files(rpc)).await?)
147	    } else {
148	        None
149	    };
150	
151	    let descriptions = memo.descriptions.lock().unwrap_or_else(PoisonError::into_inner);
152	    let tags = memo.tags.lock().unwrap_or_else(PoisonError::into_inner);
153	    let mut found = Vec::with_capacity(asked.len());
154	    for (prop, slots) in asked.iter().zip(&declares) {
155	        let key = jsdoc_key(prop.property);
156	        let mut interfaces = prop.property.declarations.iter().zip(slots).map(|(declaration, slot)| {
157	            let parent = slot.as_ref()?.0.as_ref()?;
158	            let name = parents.get(parent).cloned().flatten()?;
159	            let file = declared_in(declaration);
160	            let file_name = files.and_then(|files| files.get(file)).cloned().unwrap_or_else(|| file.to_string());
161	            Some(PropParent { name, file_name })
162	        });
163	        // react-docgen-typescript's `parent`: the first declaration's, and only when an interface holds it.
164	        let parent = interfaces.next().flatten();
165	        let declarations = parent.iter().cloned().chain(interfaces.flatten()).collect();
166	        found.push(Declared {
167	            description: if prop.description {
168	                descriptions.get(&key).cloned().unwrap_or_default()
169	            } else {
170	                String::new()
171	            },
172	            tags: if prop.tags { tags.get(&key).cloned().unwrap_or_default() } else { BTreeMap::new() },
173	            parent,
174	            declarations,
175	        });
176	    }
177	    Ok(found)
178	}
179	
180	/// Whether the property is the symbol its one declaration declares, a member of the parent it names: then that
181	/// declaration need not be asked for its symbol.
182	fn is_own_member(property: &SymbolInfo) -> bool {
183	    property.parent.is_some() && property.declarations.len() == 1
184	}
185	
186	/// The name of each parent `declares` names, when it is an interface: asked once per snapshot, in one round trip for
187	/// those not named before.
188	async fn parent_names(
189	    rpc: &Rpc,
190	    memo: &Memo,
191	    declares: &[Vec<DeclaredSymbol>],
192	) -> Result<FxHashMap<CompactSymbol, Option<String>>, CallError> {
193	    let mut known: FxHashMap<CompactSymbol, Option<String>> = FxHashMap::default();
194	    let mut unseen: Vec<(CompactSymbol, &SymbolRef)> = Vec::new();
195	    {
196	        let seen = memo.parents.lock().unwrap_or_else(PoisonError::into_inner);
197	        let named = declares.iter().flatten().flatten();
198	        for (parent, reference) in named.filter_map(|(parent, reference)| Some((parent.as_ref()?, reference))) {
199	            if known.contains_key(parent) {
200	                continue;
201	            }
202	            match seen.get(parent) {
203	                Some(name) => {
204	                    known.insert(parent.clone(), name.clone());
205	                }
206	                None => {
207	                    known.insert(parent.clone(), None);
208	                    unseen.push((parent.clone(), reference));
209	                }
210	            }
211	        }
212	    }
213	    if unseen.is_empty() {
214	        return Ok(known);
215	    }
216	    let requests =
217	        unseen.iter().map(|(_, symbol)| ("getParentOfSymbolForChecker", Asking::Symbol { symbol })).collect();
218	    let answers = rpc.batch(requests).await?;
219	    let mut seen = memo.parents.lock().unwrap_or_else(PoisonError::into_inner);
220	    for ((parent, _), answer) in unseen.into_iter().zip(answers) {
221	        let symbol: Option<SymbolInfo> = decode(&answer)?;
222	        let name = symbol.filter(|symbol| symbol.flags & flag::SYMBOL_INTERFACE != 0).map(|symbol| symbol.name);
223	        seen.insert(parent.clone(), name.clone());
224	        known.insert(parent, name);
225	    }
226	    Ok(known)
227	}
228	
229	/// The program's files, by their own path and by its lower-cased form, the first file of a lower-cased form winning.
230	/// A declaration in a file the list does not name keeps the checker's spelling.
231	async fn program_files(rpc: &Rpc) -> Result<FxHashMap<String, String>, CallError> {
232	    let names = rpc.source_file_names().await?;
233	    let mut files = FxHashMap::default();
234	    for name in &names {
235	        files.insert(name.clone(), name.clone());
236	    }
237	    for name in names {
238	        files.entry(name.to_lowercase()).or_insert(name);
239	    }
240	    Ok(files)
241	}
242	
243	/// Each source, by its name and the file as the checker keys it, as a prop's `parent` names it ([`declared`]): the file
244	/// on disk, or the checker's spelling where the program does not name it.
245	pub(crate) async fn as_parents(
246	    rpc: &Rpc,
247	    memo: &Memo,
248	    sources: Vec<(String, String)>,
249	) -> Result<Vec<PropParent>, CallError> {
250	    if sources.is_empty() {
251	        return Ok(Vec::new());
252	    }
253	    let files = memo.files.get_or_try_init(|| program_files(rpc)).await?;
254	    Ok(sources
255	        .into_iter()
256	        .map(|(name, file)| PropParent { name, file_name: files.get(&file).cloned().unwrap_or(file) })
257	        .collect())
258	}
259	
260	/// A prop's tags as the structural pass keys them: by name, the last of a repeated tag winning, its text trimmed, and a
261	/// `@param` by `param:<parameter>` with the text after the parameter's name, which the checker renders as the text's
262	/// first word.
263	fn tags_of(tags: Vec<JsDocTag>) -> BTreeMap<String, String> {
264	    tags.into_iter()
265	        .map(|tag| {
266	            let text = tag.text.unwrap_or_default();
267	            let text = text.trim();
268	            match (tag.name.as_str(), text.split_once(char::is_whitespace)) {
269	                ("param", Some((parameter, rest))) => (format!("param:{parameter}"), rest.trim().to_string()),
270	                ("param", None) if !text.is_empty() => (format!("param:{text}"), String::new()),
271	                _ => (tag.name, text.to_string()),
272	            }
273	        })
274	        .collect()
275	}
276	
277	#[cfg(test)]
278	mod tests {
279	    use serde_json::json;
280	
281	    use super::*;
282	
283	    fn tag(name: &str, text: Option<&str>) -> JsDocTag {
284	        JsDocTag { name: name.to_string(), text: text.map(str::to_string) }
285	    }
286	
287	    fn symbol(declarations: &[&str], parent: Option<u64>) -> SymbolInfo {
288	        SymbolInfo {
289	            reference: json!({ "id": 7 }).into(),
290	            name: "x".to_string(),
291	            flags: 4,
292	            declarations: declarations.iter().map(|declaration| declaration.to_string()).collect(),
293	            parent: parent.map(|id| CompactSymbol { id, file: None }),
294	        }
295	    }
296	
297	    #[test]
298	    fn a_tag_is_keyed_by_name_with_its_text_trimmed_and_a_repeated_tag_keeps_the_last() {
299	        let tags = tags_of(vec![
300	            tag("deprecated", None),
301	            tag("see", Some(" https://a.example ")),
302	            tag("since", Some("2.0")),
303	            tag("see", Some("https://b.example")),
304	        ]);
305	
306	        assert_eq!(
307	            tags,
308	            BTreeMap::from([
309	                ("deprecated".to_string(), String::new()),
310	                ("see".to_string(), "https://b.example".to_string()),
