                        .get(1, || async move {
                            asked.fetch_add(1, Ordering::Relaxed);
                            Ok(2)
                        })
                        .await
                }
            });
            tokio::task::yield_now().await;
            release.send(()).unwrap();
            assert_eq!((first.await.unwrap().unwrap(), second.await.unwrap().unwrap()), (1, 1));
